    """Add bits=16, data_type=float entries for the target layer names."""
    for cfg_path in [MODEL_DIR / "quantization_config.json", MODEL_DIR / "config.json"]:
        cfg = json.loads(cfg_path.read_text())
        if "quantization_config" in cfg and isinstance(cfg["quantization_config"], dict):
            qc = cfg["quantization_config"]
