        for k in sorted(target_keys):
            extra[k] = {"bits": 16, "data_type": "float"}
        cfg_path.write_text(json.dumps(cfg, indent=2) + "\n")
        print(f"  patched {cfg_path} ({sum(1 for k in extra if k in target_keys)} new fp16 entries)")

